#!/usr/bin/env python3
"""Reference-integrity checker for FHIR-like Bundles (synthetic data only).

A bundle looks like:
    {"resourceType": "Bundle",
     "entry": [{"resource": {"resourceType": ..., "id": ..., ...}}, ...]}

check(bundle) returns findings:
  - dangling references: subject.reference / partOf.reference whose
    target type/id is absent from the bundle
  - duplicate ids within a resource type
  - partOf cycles among Encounters (DFS, cycle path reported)

CLI: python bundle_check.py file.json   -> exit 1 if any findings, else 0.
"""

import json
import sys


def _index_resources(entries):
    """Return ({resourceType: set(ids)}, {type/id: resource}, [dup findings])."""
    by_type = {}
    resources = {}
    duplicates = []
    seen = set()
    for entry in entries:
        res = entry.get("resource") or {}
        rtype = res.get("resourceType")
        rid = res.get("id")
        if not rtype or not rid:
            continue
        key = (rtype, rid)
        by_type.setdefault(rtype, set()).add(rid)
        if key in seen:
            duplicates.append(
                {"kind": "duplicate-id", "resourceType": rtype, "id": rid}
            )
        else:
            seen.add(key)
            resources["{}/{}".format(rtype, rid)] = res
    return by_type, resources, duplicates


def _dangling_refs(entries, by_type):
    dangling = []
    for entry in entries:
        res = entry.get("resource") or {}
        rtype = res.get("resourceType")
        rid = res.get("id")
        if not rtype or not rid:
            continue
        refs = []
        subject = (res.get("subject") or {}).get("reference")
        if subject:
            refs.append(subject)
        part_of = (res.get("partOf") or {}).get("reference")
        if part_of:
            refs.append(part_of)
        for ref in refs:
            target_type, _, target_id = ref.partition("/")
            if target_id and target_id not in by_type.get(target_type, set()):
                dangling.append(
                    {
                        "kind": "dangling-reference",
                        "source": "{}/{}".format(rtype, rid),
                        "reference": ref,
                    }
                )
    return dangling


def _part_of_cycles(resources):
    """DFS over Encounter.partOf edges; report each distinct cycle path."""
    graph = {}
    for key, res in sorted(resources.items()):
        if res.get("resourceType") != "Encounter":
            continue
        part_of = (res.get("partOf") or {}).get("reference")
        if part_of and part_of in resources:
            graph[key] = part_of

    WHITE, GRAY, BLACK = 0, 1, 2
    color = {node: WHITE for node in graph}
    cycles = []

    def dfs(node, stack):
        color[node] = GRAY
        stack.append(node)
        nxt = graph.get(node)
        if nxt is not None:
            if color[nxt] == GRAY:
                i = stack.index(nxt)
                cycles.append(stack[i:] + [nxt])  # closed cycle path
            elif color[nxt] == WHITE:
                dfs(nxt, stack)
        stack.pop()
        color[node] = BLACK

    # deterministic iteration; skip nodes already inside a reported cycle
    reported = set()
    for node in sorted(graph):
        if color[node] == WHITE:
            dfs(node, [])
            if cycles:
                last = cycles[-1]
                cycle_set = set(last[:-1])
                if cycle_set <= reported:
                    cycles.pop()
                    continue
                reported |= cycle_set
    return [
        {"kind": "partOf-cycle", "cycle": cycle} for cycle in cycles
    ]


def check(bundle):
    """Return the list of reference-integrity findings (empty list == clean)."""
    entries = bundle.get("entry", []) if isinstance(bundle, dict) else []
    by_type, resources, duplicates = _index_resources(entries)
    return (
        _dangling_refs(entries, by_type)
        + duplicates
        + _part_of_cycles(resources)
    )


def main(argv):
    if len(argv) != 2:
        print("usage: python bundle_check.py file.json", file=sys.stderr)
        return 2
    with open(argv[1], "r", encoding="utf-8") as fh:
        bundle = json.load(fh)
    findings = check(bundle)
    for finding in findings:
        print(json.dumps(finding))
    print(
        "{}: {} finding(s)".format(argv[1], len(findings)),
        file=sys.stderr,
    )
    return 1 if findings else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

